import java.util.*;

class Solution {
    public TreeNode deleteBST(TreeNode root, int key) {
        List<Integer> values = new ArrayList<>();
        inorder(root, values);
        boolean removed = false;
        List<Integer> kept = new ArrayList<>();
        for (int value : values) {
            if (!removed && value == key) {
                removed = true;
                continue;
            }
            kept.add(value);
        }
        return build(kept, 0, kept.size() - 1);
    }

    private void inorder(TreeNode node, List<Integer> values) {
        if (node == null) {
            return;
        }
        inorder(node.left, values);
        values.add(node.val);
        inorder(node.right, values);
    }

    private TreeNode build(List<Integer> values, int left, int right) {
        if (left > right) {
            return null;
        }
        int mid = (left + right) / 2;
        TreeNode node = new TreeNode(values.get(mid));
        node.left = build(values, left, mid - 1);
        node.right = build(values, mid + 1, right);
        return node;
    }
}
